@Test
public void stopStartNative() throws IOException {
    //TODO why does trunk need GOSSIP for native to work but no other branch does?
    try (Cluster cluster = init(Cluster.build(1).withConfig(c -> c.with(Feature.GOSSIP, Feature.NATIVE_PROTOCOL)).start())) {
        IInvokableInstance node = cluster.get(1);
        assertTransportStatus(node, "binary", true);
        node.nodetoolResult("disablebinary").asserts().success();
        assertTransportStatus(node, "binary", false);
        node.nodetoolResult("enablebinary").asserts().success();
        assertTransportStatus(node, "binary", true);
        // now use it to make sure it still works!
        cluster.schemaChange("CREATE TABLE " + KEYSPACE + ".tbl (pk int, value int, PRIMARY KEY (pk))");
        try (com.datastax.driver.core.Cluster client = com.datastax.driver.core.Cluster.builder().addContactPoints(node.broadcastAddress().getAddress()).build();
            Session session = client.connect()) {
            session.execute("INSERT INTO " + KEYSPACE + ".tbl (pk, value) VALUES (?, ?)", 0, 0);
        }
        SimpleQueryResult qr = cluster.coordinator(1).executeWithResult("SELECT * FROM " + KEYSPACE + ".tbl", ConsistencyLevel.ALL);
        AssertUtils.assertRows(qr, QueryResults.builder().row(0, 0).build());
    }
}

@Test(timeout = 10 * 60 * 1000)
public void testFailingMessage() throws IOException {
    final int replica = 1;
    final int coordinator = 2;
    String tableName = getCfName(messageType, parallelism, withTracing);
    String fqtn = KEYSPACE + "." + tableName;
    CLUSTER.schemaChange("CREATE TABLE " + fqtn + " (k INT, PRIMARY KEY (k))");
    // create data which will NOT conflict
    int lhsOffset = 10;
    int rhsOffset = 20;
    int limit = rhsOffset + (rhsOffset - lhsOffset);
    // setup data which is consistent on both sides
    for (int i = 0; i < lhsOffset; i++) CLUSTER.coordinator(replica).execute("INSERT INTO " + fqtn + " (k) VALUES (?)", ConsistencyLevel.ALL, i);
    // create data on LHS which does NOT exist in RHS
    for (int i = lhsOffset; i < rhsOffset; i++) CLUSTER.get(replica).executeInternal("INSERT INTO " + fqtn + " (k) VALUES (?)", i);
    // create data on RHS which does NOT exist in LHS
    for (int i = rhsOffset; i < limit; i++) CLUSTER.get(coordinator).executeInternal("INSERT INTO " + fqtn + " (k) VALUES (?)", i);
    // at this point, the two nodes should be out of sync, so confirm missing data
    // node 1
    Object[][] node1Records = toRows(IntStream.range(0, rhsOffset));
    Object[][] node1Actuals = toNaturalOrder(CLUSTER.get(replica).executeInternal("SELECT k FROM " + fqtn));
    Assert.assertArrayEquals(node1Records, node1Actuals);
    // node 2
    Object[][] node2Records = toRows(IntStream.concat(IntStream.range(0, lhsOffset), IntStream.range(rhsOffset, limit)));
    Object[][] node2Actuals = toNaturalOrder(CLUSTER.get(coordinator).executeInternal("SELECT k FROM " + fqtn));
    Assert.assertArrayEquals(node2Records, node2Actuals);
    // Inject the failure
    CLUSTER.get(replica).runOnInstance(() -> setup.run());
    // run a repair which is expected to fail
    List<String> repairStatus = CLUSTER.get(coordinator).callOnInstance(() -> {
        // need all ranges on the host
        String ranges = StorageService.instance.getLocalAndPendingRanges(KEYSPACE).stream().map(r -> r.left + ":" + r.right).collect(Collectors.joining(","));
        Map<String, String> args = new HashMap<String, String>() {

            {
                put(RepairOption.PARALLELISM_KEY, parallelism.getName());
                put(RepairOption.PRIMARY_RANGE_KEY, "false");
                put(RepairOption.INCREMENTAL_KEY, "false");
                put(RepairOption.TRACE_KEY, Boolean.toString(withTracing));
                put(RepairOption.PULL_REPAIR_KEY, "false");
                put(RepairOption.FORCE_REPAIR_KEY, "false");
                put(RepairOption.RANGES_KEY, ranges);
                put(RepairOption.COLUMNFAMILIES_KEY, tableName);
            }
        };
        int cmd = StorageService.instance.repairAsync(KEYSPACE, args);
        Assert.assertFalse("repair return status was 0, expected non-zero return status, 0 indicates repair not submitted", cmd == 0);
        List<String> status;
        do {
            Uninterruptibles.sleepUninterruptibly(100, TimeUnit.MILLISECONDS);
            status = StorageService.instance.getParentRepairStatus(cmd);
        } while (status == null || status.get(0).equals(ParentRepairStatus.IN_PROGRESS.name()));
        return status;
    });
    Assert.assertEquals(repairStatus.toString(), ParentRepairStatus.FAILED, ParentRepairStatus.valueOf(repairStatus.get(0)));
    // its possible that the coordinator gets the message that the replica failed before the replica completes
    // shutting down; this then means that isKilled could be updated after the fact
    IInvokableInstance replicaInstance = CLUSTER.get(replica);
    while (replicaInstance.killAttempts() <= 0) Uninterruptibles.sleepUninterruptibly(50, TimeUnit.MILLISECONDS);
    Assert.assertEquals("replica should be killed", 1, replicaInstance.killAttempts());
    Assert.assertEquals("coordinator should not be killed", 0, CLUSTER.get(coordinator).killAttempts());
}

@Test
public void test() throws Throwable {
    try (final Cluster cluster = init(builder().withNodes(1).withConfig(updater -> updater.with(NETWORK, GOSSIP, NATIVE_PROTOCOL)).start())) {
        final IInvokableInstance node = cluster.get(1);
        // using driver path is important because dtest API and query execution does not invoke code
        // in Cassandra where events are propagated to logger
        try (com.datastax.driver.core.Cluster c = com.datastax.driver.core.Cluster.builder().addContactPoint("127.0.0.1").build();
            Session s = c.connect()) {
            s.execute("CREATE KEYSPACE fql_ks WITH replication = {'class': 'SimpleStrategy', 'replication_factor': 1};");
            node.nodetool("enablefullquerylog", "--path", temporaryFolder.getRoot().getAbsolutePath());
            s.execute("CREATE TABLE fql_ks.fql_table (id int primary key);");
            s.execute("INSERT INTO fql_ks.fql_table (id) VALUES (1)");
            node.nodetool("disablefullquerylog");
            // here we are dropping and we expect that ddl replay will reconstruct it
            node.executeInternal("DROP TABLE fql_ks.fql_table;");
            // without --replay-ddl-statements, the replay will fail on insert because underlying table is not there
            final ToolResult negativeRunner = ToolRunner.invokeClass("org.apache.cassandra.fqltool.FullQueryLogTool", "replay", "--keyspace", "fql_ks", "--target", "127.0.0.1", "--", temporaryFolder.getRoot().getAbsolutePath());
            assertEquals(0, negativeRunner.getExitCode());
            try {
                node.executeInternalWithResult("SELECT * from fql_ks.fql_table");
                fail("This query should fail because we do not expect fql_ks.fql_table to be created!");
            } catch (final Exception ex) {
                assertTrue(ex.getMessage().contains("table fql_table does not exist"));
            }
            // here we replay with --replay-ddl-statements so table will be created and insert will succeed
            final ToolResult positiveRunner = ToolRunner.invokeClass("org.apache.cassandra.fqltool.FullQueryLogTool", "replay", "--keyspace", "fql_ks", "--target", "127.0.0.1", // important
            "--replay-ddl-statements", "--", temporaryFolder.getRoot().getAbsolutePath());
            assertEquals(0, positiveRunner.getExitCode());
            assertRows(node.executeInternalWithResult("SELECT * from fql_ks.fql_table"), QueryResults.builder().row(1).build());
        }
    }
}

@Test
public void testAddAndUDTField() throws IOException {
    try (Cluster cluster = init(Cluster.build(1).start())) {
        cluster.schemaChange("create type " + KEYSPACE + ".a (foo text)");
        cluster.schemaChange("create table " + KEYSPACE + ".x (id int, ck frozen<a>, i int, primary key (id, ck))");
        for (int i = 0; i < 10; i++) cluster.coordinator(1).execute("insert into " + KEYSPACE + ".x (id, ck, i) VALUES (?, " + json(i) + ", ? )", ConsistencyLevel.ALL, i, i);
        for (int i = 0; i < 10; i++) assertRows(cluster.coordinator(1).execute("select i from " + KEYSPACE + ".x WHERE id = ? and ck = " + json(i), ConsistencyLevel.ALL, i), row(i));
        cluster.schemaChange("alter type " + KEYSPACE + ".a add bar text");
        for (int i = 5; i < 15; i++) cluster.coordinator(1).execute("insert into " + KEYSPACE + ".x (id, ck, i) VALUES (?, " + json(i) + ", ? )", ConsistencyLevel.ALL, i, i);
        cluster.forEach(i -> i.flush(KEYSPACE));
        for (int i = 5; i < 15; i++) assertRows(cluster.coordinator(1).execute("select i from " + KEYSPACE + ".x WHERE id = ? and ck = " + json(i), ConsistencyLevel.ALL, i), row(i));
    }
}

@Test
public void testEmptyValue() throws IOException {
    try (Cluster cluster = init(Cluster.build(1).start())) {
        cluster.schemaChange("create type " + KEYSPACE + ".a (foo text)");
        cluster.schemaChange("create table " + KEYSPACE + ".x (id int, ck frozen<a>, i int, primary key (id, ck))");
        cluster.coordinator(1).execute("insert into " + KEYSPACE + ".x (id, ck, i) VALUES (1, system.fromjson('{\"foo\":\"\"}'), 1)", ConsistencyLevel.ALL);
        cluster.coordinator(1).execute("insert into " + KEYSPACE + ".x (id, ck, i) VALUES (1, system.fromjson('{\"foo\":\"a\"}'), 2)", ConsistencyLevel.ALL);
        cluster.forEach(i -> i.flush(KEYSPACE));
        Runnable check = () -> {
            assertRows(cluster.coordinator(1).execute("select i from " + KEYSPACE + ".x WHERE id = 1 and ck = system.fromjson('{\"foo\":\"\"}')", ConsistencyLevel.ALL), row(1));
            assertRows(cluster.coordinator(1).execute("select i from " + KEYSPACE + ".x WHERE id = 1 and ck = system.fromjson('{\"foo\":\"a\"}')", ConsistencyLevel.ALL), row(2));
        };
        check.run();
        cluster.schemaChange("alter type " + KEYSPACE + ".a add bar text");
        check.run();
        assertRows(cluster.coordinator(1).execute("select i from " + KEYSPACE + ".x WHERE id = 1 and ck = system.fromjson('{\"foo\":\"\",\"bar\":\"\"}')", ConsistencyLevel.ALL));
        cluster.coordinator(1).execute("insert into " + KEYSPACE + ".x (id, ck, i) VALUES (1, system.fromjson('{\"foo\":\"\",\"bar\":\"\"}'), 3)", ConsistencyLevel.ALL);
        check.run();
        assertRows(cluster.coordinator(1).execute("select i from " + KEYSPACE + ".x WHERE id = 1 and ck = system.fromjson('{\"foo\":\"\",\"bar\":\"\"}')", ConsistencyLevel.ALL), row(3));
    }
}

@Test
public void testUpgradeSStables() throws IOException {
    try (Cluster cluster = init(Cluster.build(1).start())) {
        cluster.schemaChange("create type " + KEYSPACE + ".a (foo text)");
        cluster.schemaChange("create table " + KEYSPACE + ".x (id int, ck frozen<a>, i int, primary key (id, ck))");
        cluster.coordinator(1).execute("insert into " + KEYSPACE + ".x (id, ck, i) VALUES (?, " + json(1) + ", ? )", ConsistencyLevel.ALL, 1, 1);
        assertRows(cluster.coordinator(1).execute("select i from " + KEYSPACE + ".x WHERE id = ? and ck = " + json(1), ConsistencyLevel.ALL, 1), row(1));
        cluster.forEach(i -> i.flush(KEYSPACE));
        assertRows(cluster.coordinator(1).execute("select i from " + KEYSPACE + ".x WHERE id = ? and ck = " + json(1), ConsistencyLevel.ALL, 1), row(1));
        cluster.schemaChange("alter type " + KEYSPACE + ".a add bar text");
        cluster.coordinator(1).execute("insert into " + KEYSPACE + ".x (id, ck, i) VALUES (?, " + json(2) + ", ? )", ConsistencyLevel.ALL, 2, 2);
        cluster.forEach(i -> i.flush(KEYSPACE));
        assertRows(cluster.coordinator(1).execute("select i from " + KEYSPACE + ".x WHERE id = ? and ck = " + json(2), ConsistencyLevel.ALL, 2), row(2));
        cluster.forEach(i -> i.runOnInstance(() -> {
