@Test
public void testWideRow() throws Exception {
    String KS = "cql_keyspace";
    String TABLE = "table1";
    int size = 30000;
    File tempdir = Files.createTempDir();
    File dataDir = new File(tempdir.getAbsolutePath() + File.separator + KS + File.separator + TABLE);
    assert dataDir.mkdirs();
    StringBuilder schemaColumns = new StringBuilder();
    StringBuilder queryColumns = new StringBuilder();
    StringBuilder queryValues = new StringBuilder();
    for (int i = 0; i < size; i++) {
        schemaColumns.append("v");
        schemaColumns.append(i);
        schemaColumns.append(" int,");
        queryColumns.append(", v");
        queryColumns.append(i);
        queryValues.append(", ?");
    }
    String schema = "CREATE TABLE cql_keyspace.table1 (" + "  k int," + "  c int," + schemaColumns.toString() + "  PRIMARY KEY (k, c)" + ")";
    String insert = "INSERT INTO cql_keyspace.table1 (k, c" + queryColumns.toString() + ") VALUES (?, ?" + queryValues.toString() + ")";
    CQLSSTableWriter writer = CQLSSTableWriter.builder().inDirectory(dataDir).forTable(schema).using(insert).withBufferSizeInMB(1).build();
    long high = 100;
    Random r = new Random(0);
    for (int i = 0; i < high; i++) {
        List<Object> values = new ArrayList<>(size + 2);
        values.add(0);
        values.add(r.nextInt());
        for (int j = 0; j < size; j++) {
            values.add(i);
        }
        writer.addRow(values);
    }
    writer.close();
}

@Test
public void testConcurrency() throws InterruptedException, IOException, ConfigurationException {
    // The goal of this test is to check for CASSANDRA-8448/CASSANDRA-9519
    double badness = DatabaseDescriptor.getDynamicBadnessThreshold();
    DatabaseDescriptor.setDynamicBadnessThreshold(0.0);
    try {
        final int ITERATIONS = 10000;
        // do this because SS needs to be initialized before DES can work properly.
        StorageService.instance.unsafeInitialize();
        SimpleSnitch ss = new SimpleSnitch();
        DynamicEndpointSnitch dsnitch = new DynamicEndpointSnitch(ss, String.valueOf(ss.hashCode()));
        InetAddressAndPort self = FBUtilities.getBroadcastAddressAndPort();
        EndpointsForRange.Builder replicasBuilder = EndpointsForRange.builder(ReplicaUtils.FULL_RANGE);
        // We want a big list of hosts so  sorting takes time, making it much more likely to reproduce the
        // problem we're looking for.
        for (int i = 0; i < 100; i++) for (int j = 0; j < 256; j++) replicasBuilder.add(ReplicaUtils.full(InetAddressAndPort.getByAddress(new byte[] { 127, 0, (byte) i, (byte) j })));
        EndpointsForRange replicas = replicasBuilder.build();
        ScoreUpdater updater = new ScoreUpdater(dsnitch, replicas);
        updater.start();
        EndpointsForRange result = replicas;
        for (int i = 0; i < ITERATIONS; i++) result = dsnitch.sortedByProximity(self, result);
        updater.stopped = true;
        updater.join();
    } finally {
        DatabaseDescriptor.setDynamicBadnessThreshold(badness);
    }
}

