@Test
public void rejectWhenAuthSetupIsNotComplete() throws Throwable {
    // IAuthorizer & IRoleManager should not be considered ready to use until
    // we know that auth setup has completed. So, even though the IAuthorizer
    // would theoretically grant access, the auth proxy should deny it if setup
    // hasn't finished.
    Map<RoleResource, Set<PermissionDetails>> permissions = ImmutableMap.of(role1, Collections.singleton(permission(role1, osBean, Permission.SELECT)));
    // verify that access is granted when setup is complete
    AuthorizationProxy proxy = new ProxyBuilder().isSuperuser((role) -> false).getPermissions(permissions::get).isAuthzRequired(() -> true).isAuthSetupComplete(() -> true).build();
    assertTrue(proxy.authorize(subject(role1.getRoleName()), "getAttribute", new Object[] { objectName(osBean), "arch" }));
    // and denied when it isn't
    proxy = new ProxyBuilder().isSuperuser((role) -> false).getPermissions(permissions::get).isAuthzRequired(() -> true).isAuthSetupComplete(() -> false).build();
    assertFalse(proxy.authorize(subject(role1.getRoleName()), "getAttribute", new Object[] { objectName(osBean), "arch" }));
}

