@Test
public void testKeys() {
    TableId id1 = TableId.generate();
    byte[] b1 = { 1, 2, 3, 4 };
    RowCacheKey key1 = new RowCacheKey(id1, null, ByteBuffer.wrap(b1));
    TableId id2 = TableId.fromString(id1.toString());
    byte[] b2 = { 1, 2, 3, 4 };
    RowCacheKey key2 = new RowCacheKey(id2, null, ByteBuffer.wrap(b2));
    assertEquals(key1, key2);
    assertEquals(key1.hashCode(), key2.hashCode());
    TableMetadata tm = TableMetadata.builder("ks", "tab", id1).addPartitionKeyColumn("pk", UTF8Type.instance).build();
    assertTrue(key1.sameTable(tm));
    byte[] b3 = { 1, 2, 3, 5 };
    RowCacheKey key3 = new RowCacheKey(id1, null, ByteBuffer.wrap(b3));
    assertNotSame(key1, key3);
    assertNotSame(key1.hashCode(), key3.hashCode());
    // with index name
    key1 = new RowCacheKey(id1, "indexFoo", ByteBuffer.wrap(b1));
    assertNotSame(key1, key2);
    assertNotSame(key1.hashCode(), key2.hashCode());
    key2 = new RowCacheKey(id2, "indexFoo", ByteBuffer.wrap(b2));
    assertEquals(key1, key2);
    assertEquals(key1.hashCode(), key2.hashCode());
    tm = TableMetadata.builder("ks", "tab.indexFoo", id1).kind(TableMetadata.Kind.INDEX).addPartitionKeyColumn("pk", UTF8Type.instance).indexes(Indexes.of(IndexMetadata.fromSchemaMetadata("indexFoo", IndexMetadata.Kind.KEYS, Collections.emptyMap()))).build();
    assertTrue(key1.sameTable(tm));
    key3 = new RowCacheKey(id1, "indexFoo", ByteBuffer.wrap(b3));
    assertNotSame(key1, key3);
    assertNotSame(key1.hashCode(), key3.hashCode());
}

@Test
public void testShutdown() throws ExecutionException, InterruptedException, IOException {
    DebuggableScheduledThreadPoolExecutor testPool = new DebuggableScheduledThreadPoolExecutor("testpool");
    final AtomicInteger value = new AtomicInteger(0);
    //Normal scheduled task
    ScheduledFuture future = testPool.schedule(new Runnable() {

        public void run() {
            value.incrementAndGet();
        }
    }, 1, TimeUnit.SECONDS);
    future.get();
    assert value.get() == 1;
    //Shut down before schedule
    future = testPool.schedule(new Runnable() {

        public void run() {
            value.incrementAndGet();
        }
    }, 10, TimeUnit.SECONDS);
    StorageService.instance.drain();
    testPool.shutdown();
    future.get();
    assert value.get() == 2;
    //Now shut down verify task isn't just swallowed
    future = testPool.schedule(new Runnable() {

        public void run() {
            value.incrementAndGet();
        }
    }, 1, TimeUnit.SECONDS);
    try {
        future.get(2, TimeUnit.SECONDS);
        Assert.fail("Task should be cancelled");
    } catch (CancellationException e) {
    } catch (TimeoutException e) {
        Assert.fail("Task should be cancelled");
    }
    assert future.isCancelled();
    assert value.get() == 2;
}

@Test
public void testSerialization() {
    LinkedBlockingQueue<Runnable> q = new LinkedBlockingQueue<Runnable>(1);
    DebuggableThreadPoolExecutor executor = new DebuggableThreadPoolExecutor(1, Integer.MAX_VALUE, TimeUnit.MILLISECONDS, q, new NamedThreadFactory("TEST"));
    WrappedRunnable runnable = new WrappedRunnable() {

        public void runMayThrow() throws InterruptedException {
            Thread.sleep(50);
        }
    };
    long start = System.nanoTime();
    for (int i = 0; i < 10; i++) {
        executor.execute(runnable);
    }
    assert q.size() > 0 : q.size();
    while (executor.getCompletedTaskCount() < 10) continue;
    long delta = TimeUnit.NANOSECONDS.toMillis(System.nanoTime() - start);
    assert delta >= 9 * 50 : delta;
}

@Test
public void testExecuteFutureTaskWhileTracing() {
    LinkedBlockingQueue<Runnable> q = new LinkedBlockingQueue<Runnable>(1);
    DebuggableThreadPoolExecutor executor = new DebuggableThreadPoolExecutor(1, Integer.MAX_VALUE, TimeUnit.MILLISECONDS, q, new NamedThreadFactory("TEST"));
    Runnable test = () -> executor.execute(failingTask());
    try {
        // make sure the non-tracing case works
        Throwable cause = catchUncaughtExceptions(test);
        Assert.assertEquals(DebuggingThrowsException.class, cause.getClass());
        // tracing should have the same semantics
        cause = catchUncaughtExceptions(() -> withTracing(test));
        Assert.assertEquals(DebuggingThrowsException.class, cause.getClass());
    } finally {
        executor.shutdown();
    }
}

