    assertRowsNet(executeDescribeNet("DESCRIBE TABLE " + KEYSPACE + "." + table + " WITH INTERNALS"), row(KEYSPACE, "table", table, tableCreateStatement + "
" + dropStatement + "
" + addStatement));
