    createTable("CREATE TABLE %s (k int, c int, l text, " + "m map<text, text>, " + "fm frozen<map<text, text>>, " + "sm map<text, text> STATIC, " + "fsm frozen<map<text, text>> STATIC, " + "o int, PRIMARY KEY (k, c))");
