    execute("INSERT INTO %s(k, c, l, m, fm, o) VALUES (0, 1, 'foobar', ?, ?, 42)", map("1", "value1_2", "333", "value333_2"), map("1", "fvalue1_2", "333", "fvalue333_2"));
