    createIndex(format("CREATE CUSTOM INDEX v1_idx on %%s(v1) USING '%s' WITH OPTIONS = {'mode' : 'PREFIX'}", SASIIndex.class.getName()));
    createIndex(format("CREATE CUSTOM INDEX v2_idx on %%s(v2) USING '%s' WITH OPTIONS = {'mode' : 'CONTAINS'}", SASIIndex.class.getName()));
    createIndex(format("CREATE CUSTOM INDEX v3_idx on %%s(v3) USING '%s'", SASIIndex.class.getName()));
    forcePreparedValues();
    // prefix mode indexes support prefix/contains/matches
    assertInvalidMessage("c1 LIKE '%<term>' abc is only supported on properly indexed columns", "SELECT * FROM %s WHERE c1 LIKE ?", "%abc");
    assertInvalidMessage("c1 LIKE '%<term>%' abc is only supported on properly indexed columns", "SELECT * FROM %s WHERE c1 LIKE ?", "%abc%");
    execute("SELECT * FROM %s WHERE c1 LIKE ?", "abc%");
    execute("SELECT * FROM %s WHERE c1 LIKE ?", "abc");
    assertInvalidMessage("v1 LIKE '%<term>' abc is only supported on properly indexed columns", "SELECT * FROM %s WHERE v1 LIKE ?", "%abc");
    assertInvalidMessage("v1 LIKE '%<term>%' abc is only supported on properly indexed columns", "SELECT * FROM %s WHERE v1 LIKE ?", "%abc%");
    execute("SELECT * FROM %s WHERE v1 LIKE ?", "abc%");
    execute("SELECT * FROM %s WHERE v1 LIKE ?", "abc");
    // contains mode indexes support prefix/suffix/contains/matches
    execute("SELECT * FROM %s WHERE c2 LIKE ?", "abc%");
    execute("SELECT * FROM %s WHERE c2 LIKE ?", "%abc");
    execute("SELECT * FROM %s WHERE c2 LIKE ?", "%abc%");
    execute("SELECT * FROM %s WHERE c2 LIKE ?", "abc");
    execute("SELECT * FROM %s WHERE v2 LIKE ?", "abc%");
    execute("SELECT * FROM %s WHERE v2 LIKE ?", "%abc");
    execute("SELECT * FROM %s WHERE v2 LIKE ?", "%abc%");
    execute("SELECT * FROM %s WHERE v2 LIKE ?", "abc");
    // LIKE is not supported on indexes of non-literal values
    // this is rejected before binding, so the value isn't available in the error message
    assertInvalidMessage("LIKE restriction is only supported on properly indexed columns. v3 LIKE ? is not valid", "SELECT * FROM %s WHERE v3 LIKE ?", "%abc");
    assertInvalidMessage("LIKE restriction is only supported on properly indexed columns. v3 LIKE ? is not valid", "SELECT * FROM %s WHERE v3 LIKE ?", "%abc%");
    assertInvalidMessage("LIKE restriction is only supported on properly indexed columns. v3 LIKE ? is not valid", "SELECT * FROM %s WHERE v3 LIKE ?", "%abc%");
    assertInvalidMessage("LIKE restriction is only supported on properly indexed columns. v3 LIKE ? is not valid", "SELECT * FROM %s WHERE v3 LIKE ?", "abc");
}

