    // specifying a function using "keyspace.functionname" is a syntax error
    assertInvalidMessage(// specifying a function using "keyspace.functionname" is a syntax error
    "expecting EOF", "CREATE AGGREGATE " + KEYSPACE_PER_TEST + ".test_wrong_ks(int) " + "SFUNC " + shortFunctionName(fState) + ' ' + "STYPE " + type + " " + "FINALFUNC " + fFinalWrong + ' ' + "INITCOND 1");
    // specifying a function using "keyspace.functionname" is a syntax error
    assertInvalidMessage(// specifying a function using "keyspace.functionname" is a syntax error
    "expecting EOF", "CREATE AGGREGATE " + KEYSPACE_PER_TEST + ".test_wrong_ks(int) " + "SFUNC " + shortFunctionName(fState) + ' ' + "STYPE " + type + ' ' + "FINALFUNC " + SchemaConstants.SYSTEM_KEYSPACE_NAME + ".min " + "INITCOND 1");
}

