    assertRows(execute("SELECT a, b, s, d FROM %s WHERE a = 2"), row(2, 1, 200, null), row(2, 2, 200, null));
    // rejected: IN doesn't contain null
    assertRows(execute("UPDATE %s SET s = 30 WHERE a = 3 IF s IN ?", list(10, 20, 30)), row(false, null));
    assertRows(execute("SELECT * FROM %s WHERE a = 3"), row(3, 1, null, null), row(3, 2, null, null));
    assertRows(execute("UPDATE %s SET s = 400 WHERE a = 4 IF s IN (10,20,NULL)"), row(true));
    assertRows(execute("SELECT * FROM %s WHERE a = 4"), row(4, 1, 400, null), row(4, 2, 400, null));
    // rejected: comparing number with NULL always returns false
    for (String operator : new String[] { ">", "<", ">=", "<=", "=" }) {
        assertRows(execute("UPDATE %s SET s = 50 WHERE a = 5 IF s " + operator + " 3"), row(false, null));
        assertRows(execute("SELECT * FROM %s WHERE a = 5"), row(5, 1, null, null), row(5, 2, null, null));
    }
    assertRows(execute("UPDATE %s SET s = 500 WHERE a = 5 IF s != 5"), row(true));
    assertRows(execute("SELECT a, b, s, d FROM %s WHERE a = 5"), row(5, 1, 500, null), row(5, 2, 500, null));
    // Similar test, although with two static columns to test limits
    createTable("CREATE TABLE %s (a int, b int, s1 int static, s2 int static, d int, PRIMARY KEY (a, b))");
    for (int i = 1; i <= 5; i++) for (int j = 0; j < 5; j++) execute("INSERT INTO %s (a, b, d) VALUES (?, ?, ?)", i, j, i + j);
    assertRows(execute("UPDATE %s SET s2 = 100 WHERE a = 1 IF s1 = NULL"), row(true));
    execute("INSERT INTO %s (a, b, s1) VALUES (?, ?, ?)", 2, 2, 2);
    assertRows(execute("UPDATE %s SET s1 = 100 WHERE a = 2 IF s2 = NULL"), row(true));
    execute("INSERT INTO %s (a, b, s1) VALUES (?, ?, ?)", 2, 2, 2);
    assertRows(execute("UPDATE %s SET s1 = 100 WHERE a = 2 IF s2 = NULL"), row(true));
}

