@Test
public void testConditionalDeletesWithNonExistingValuesWithBatch() throws Throwable {
    createTable("CREATE TABLE %s (a int, b int, s1 int static, s2 int static, v int, PRIMARY KEY (a, b))");
    assertRows(execute("BEGIN BATCH\n" + "INSERT INTO %1$s (a, b, s1, v) values (2, 2, 2, 2);\n" + "DELETE s1 FROM %1$s WHERE a = 2 IF s2 = null;\n" + "APPLY BATCH"), row(true));
    assertRows(execute("SELECT * FROM %s WHERE a = 2"), row(2, 2, null, null, 2));
    // rejected: comparing number with non-existing value always returns false
    for (String operator : new String[] { ">", "<", ">=", "<=", "=" }) {
        assertRows(execute("BEGIN BATCH\n" + "INSERT INTO %1$s (a, b, s1, v) values (3, 3, 3, 3);\n" + "DELETE s1 FROM %1$s WHERE a = 3 IF s2 " + operator + " 5;\n" + "APPLY BATCH"), row(false));
        assertEmpty(execute("SELECT * FROM %s WHERE a = 3"));
    }
    // rejected: IN doesn't contain null
    assertRows(execute("BEGIN BATCH\n" + "INSERT INTO %1$s (a, b, s1, v) values (6, 6, 6, 6);\n" + "DELETE s1 FROM %1$s WHERE a = 6 IF s2 IN (1,2,3);\n" + "APPLY BATCH"), row(false));
    assertEmpty(execute("SELECT * FROM %s WHERE a = 6"));
    // Note that on equal timestamp, tombstone wins so the DELETE wins
    assertRows(execute("BEGIN BATCH\n" + "INSERT INTO %1$s (a, b, s1, v) values (4, 4, 4, 4);\n" + "DELETE s1 FROM %1$s WHERE a = 4 IF s2 = null;\n" + "APPLY BATCH"), row(true));
    assertRows(execute("SELECT * FROM %s WHERE a = 4"), row(4, 4, null, null, 4));
    // Note that on equal timestamp, tombstone wins so the DELETE wins
    assertRows(execute("BEGIN BATCH\n" + "INSERT INTO %1$s (a, b, s1, v) VALUES (5, 5, 5, 5);\n" + "DELETE s1 FROM %1$s WHERE a = 5 IF s1 IN (1,2,null);\n" + "APPLY BATCH"), row(true));
    assertRows(execute("SELECT * FROM %s WHERE a = 5"), row(5, 5, null, null, 5));
    // Note that on equal timestamp, tombstone wins so the DELETE wins
    assertRows(execute("BEGIN BATCH\n" + "INSERT INTO %1$s (a, b, s1, v) values (7, 7, 7, 7);\n" + "DELETE s1 FROM %1$s WHERE a = 7 IF s2 != 7;\n" + "APPLY BATCH"), row(true));
    assertRows(execute("SELECT * FROM %s WHERE a = 7"), row(7, 7, null, null, 7));
}

/**
 * Test for CASSANDRA-12060, using a table without clustering.
 */
@Test
public void testMultiExistConditionOnSameRowNoClustering() throws Throwable {
    createTable("CREATE TABLE %s (k int PRIMARY KEY, v1 text, v2 text)");
    // Multiple inserts on the same row with not exist conditions
    assertRows(execute("BEGIN BATCH " + "INSERT INTO %1$s (k, v1) values (0, 'foo') IF NOT EXISTS; " + "INSERT INTO %1$s (k, v2) values (0, 'bar') IF NOT EXISTS; " + "APPLY BATCH"), row(true));
    assertRows(execute("SELECT * FROM %s WHERE k = 0"), row(0, "foo", "bar"));
    // Same, but both insert on the same column: doing so would almost surely be a user error, but that's the
    // original case reported in #12867, so being thorough.
    assertRows(execute("BEGIN BATCH " + "INSERT INTO %1$s (k, v1) values (1, 'foo') IF NOT EXISTS; " + "INSERT INTO %1$s (k, v1) values (1, 'bar') IF NOT EXISTS; " + "APPLY BATCH"), row(true));
    // As all statement gets the same timestamp, the biggest value ends up winning, so that's "foo"
    assertRows(execute("SELECT * FROM %s WHERE k = 1"), row(1, "foo", null));
    // Multiple deletes on the same row with exists conditions (note that this is somewhat non-sensical, one of the
    // delete is redundant, we're just checking it doesn't break something)
    assertRows(execute("BEGIN BATCH " + "DELETE FROM %1$s WHERE k = 0 IF EXISTS; " + "DELETE FROM %1$s WHERE k = 0 IF EXISTS; " + "APPLY BATCH"), row(true));
    assertEmpty(execute("SELECT * FROM %s WHERE k = 0"));
    // Validate we can't mix different type of conditions however
    assertInvalidMessage("Cannot mix IF EXISTS and IF NOT EXISTS conditions for the same row", "BEGIN BATCH " + "INSERT INTO %1$s (k, v1) values (1, 'foo') IF NOT EXISTS; " + "DELETE FROM %1$s WHERE k = 1 IF EXISTS; " + "APPLY BATCH");
    assertInvalidMessage("Cannot mix IF conditions and IF NOT EXISTS for the same row", "BEGIN BATCH " + "INSERT INTO %1$s (k, v1) values (1, 'foo') IF NOT EXISTS; " + "UPDATE %1$s SET v2 = 'bar' WHERE k = 1 IF v1 = 'foo'; " + "APPLY BATCH");
}

