    execute("DELETE s FROM %s WHERE a = 4");
    execute("INSERT INTO %s (a, b, c, d) VALUES (1, 2, 1, 3)");
    execute("INSERT INTO %s (a, b, c, d) VALUES (1, 2, 2, 6)");
    execute("INSERT INTO %s (a, b, c, d) VALUES (1, 3, 2, 12)");
