        assertInvalidMessage("Clustering column \"c\" cannot be restricted (preceding column \"b\" is restricted by a non-EQ relation)", "SELECT * FROM %s WHERE b > 20 AND c > 30");
        assertRows(execute("SELECT * FROM %s WHERE b > 20 AND c < 30 ALLOW FILTERING"), row(21, 22, 23, 24));
        assertInvalidMessage("Clustering column \"c\" cannot be restricted (preceding column \"b\" is restricted by a non-EQ relation)", "SELECT * FROM %s WHERE b > 20 AND c < 30");
        assertRows(execute("SELECT * FROM %s WHERE b > 20 AND c = 33 ALLOW FILTERING"), row(31, 32, 33, 34));
        assertInvalidMessage("Clustering column \"c\" cannot be restricted (preceding column \"b\" is restricted by a non-EQ relation)", "SELECT * FROM %s WHERE b > 20 AND c = 33");
        assertRows(execute("SELECT * FROM %s WHERE c = 33 ALLOW FILTERING"), row(31, 32, 33, 34));
        assertInvalidMessage("PRIMARY KEY column \"c\" cannot be restricted as preceding column \"b\" is not restricted", "SELECT * FROM %s WHERE c = 33");
    });
    // --------------------------------------------------
    // Clustering column within and across partition keys
