    execute("UPDATE %s SET e = 100 WHERE a IN () AND b IN () AND c = 1 AND d IN ();");
    assertRows(execute("SELECT * FROM %s"), row(1, 1, 1, 1, 1), row(1, 1, 1, 2, 2), row(1, 1, 1, 3, 3), row(1, 1, 1, 4, 4));
