    assertRowsIgnoringOrder(execute("SELECT * from %s WHERE k = 1 AND c = 1;"), row(1, 1, 1, null));
    assertRowsIgnoringOrder(execute("SELECT k,c,b from mv WHERE k = 1 AND c = 1;"), row(1, 1, null));
