@Test
public void testDropTableWithMV() throws Throwable {
    createTable("CREATE TABLE %s (" + "a int," + "b int," + "c int," + "d int," + "PRIMARY KEY (a, b, c))");
    executeNet(protocolVersion, "USE " + keyspace());
    createView(keyspace() + ".mv1", "CREATE MATERIALIZED VIEW %s AS SELECT * FROM %%s WHERE a IS NOT NULL AND b IS NOT NULL AND c IS NOT NULL PRIMARY KEY (a, b, c)");
    try {
        executeNet(protocolVersion, "DROP TABLE " + keyspace() + ".mv1");
        Assert.fail();
    } catch (InvalidQueryException e) {
        Assert.assertEquals("Cannot use DROP TABLE on a materialized view. Please use DROP MATERIALIZED VIEW instead.", e.getMessage());
    }
}

@Test
public void testCreateMVWithFilteringOnNonPkColumn() throws Throwable {
    // SEE CASSANDRA-13798, we cannot properly support non-pk base column filtering for mv without huge storage
    // format changes.
    createTable("CREATE TABLE %s ( a int, b int, c int, d int, PRIMARY KEY (a, b, c))");
    executeNet(protocolVersion, "USE " + keyspace());
    assertInvalidMessage("Non-primary key columns can only be restricted with 'IS NOT NULL'", "CREATE MATERIALIZED VIEW " + keyspace() + ".mv AS SELECT * FROM %s " + "WHERE b IS NOT NULL AND c IS NOT NULL AND a IS NOT NULL " + "AND d = 1 PRIMARY KEY (c, b, a)");
}

@Test
public void testNonExistingOnes() throws Throwable {
    assertInvalidMessage(String.format("Materialized view '%s.view_does_not_exist' doesn't exist", KEYSPACE), "DROP MATERIALIZED VIEW " + KEYSPACE + ".view_does_not_exist");
    assertInvalidMessage("Materialized view 'keyspace_does_not_exist.view_does_not_exist' doesn't exist", "DROP MATERIALIZED VIEW keyspace_does_not_exist.view_does_not_exist");
    execute("DROP MATERIALIZED VIEW IF EXISTS " + KEYSPACE + ".view_does_not_exist");
