    LeveledCompactionStrategy lcs = (LeveledCompactionStrategy) cfs.getCompactionStrategyManager().getUnrepairedUnsafe().first();
    assertEquals(1, lcs.getLevelSize(0));
    assertTrue(cfs.getTracker().getCompacting().isEmpty());
