@Test
public void testColumnFilterSerialisationRoundTrip() throws Exception {
    TableMetadata metadata = TableMetadata.builder("ks", "table").partitioner(Murmur3Partitioner.instance).addPartitionKeyColumn("pk", Int32Type.instance).addClusteringColumn("ck", Int32Type.instance).addRegularColumn("v1", Int32Type.instance).addRegularColumn("v2", Int32Type.instance).addRegularColumn("v3", Int32Type.instance).build();
    ColumnMetadata v1 = metadata.getColumn(ByteBufferUtil.bytes("v1"));
    ColumnFilter columnFilter;
    columnFilter = ColumnFilter.all(metadata);
    testRoundTrip(columnFilter, ColumnFilter.Serializer.maybeUpdateForBackwardCompatility(columnFilter, MessagingService.VERSION_30), metadata, MessagingService.VERSION_30);
    testRoundTrip(columnFilter, ColumnFilter.Serializer.maybeUpdateForBackwardCompatility(columnFilter, MessagingService.VERSION_3014), metadata, MessagingService.VERSION_3014);
    testRoundTrip(columnFilter, metadata, MessagingService.VERSION_40);
    testRoundTrip(ColumnFilter.selection(metadata.regularAndStaticColumns().without(v1)), metadata, MessagingService.VERSION_30);
    testRoundTrip(ColumnFilter.selection(metadata.regularAndStaticColumns().without(v1)), metadata, MessagingService.VERSION_3014);
    testRoundTrip(ColumnFilter.selection(metadata.regularAndStaticColumns().without(v1)), metadata, MessagingService.VERSION_40);
    columnFilter = ColumnFilter.selection(metadata, metadata.regularAndStaticColumns().without(v1));
    testRoundTrip(columnFilter, ColumnFilter.Serializer.maybeUpdateForBackwardCompatility(columnFilter, MessagingService.VERSION_30), metadata, MessagingService.VERSION_30);
    testRoundTrip(columnFilter, ColumnFilter.Serializer.maybeUpdateForBackwardCompatility(columnFilter, MessagingService.VERSION_3014), metadata, MessagingService.VERSION_3014);
    testRoundTrip(columnFilter, metadata, MessagingService.VERSION_40);
    // Table with static column
    metadata = TableMetadata.builder("ks", "table").partitioner(Murmur3Partitioner.instance).addPartitionKeyColumn("pk", Int32Type.instance).addClusteringColumn("ck", Int32Type.instance).addStaticColumn("s1", Int32Type.instance).addRegularColumn("v1", Int32Type.instance).addRegularColumn("v2", Int32Type.instance).addRegularColumn("v3", Int32Type.instance).build();
    v1 = metadata.getColumn(ByteBufferUtil.bytes("v1"));
    ColumnMetadata s1 = metadata.getColumn(ByteBufferUtil.bytes("s1"));
    columnFilter = ColumnFilter.all(metadata);
    testRoundTrip(columnFilter, ColumnFilter.Serializer.maybeUpdateForBackwardCompatility(columnFilter, MessagingService.VERSION_30), metadata, MessagingService.VERSION_30);
    testRoundTrip(columnFilter, ColumnFilter.Serializer.maybeUpdateForBackwardCompatility(columnFilter, MessagingService.VERSION_3014), metadata, MessagingService.VERSION_3014);
    testRoundTrip(columnFilter, metadata, MessagingService.VERSION_40);
    testRoundTrip(ColumnFilter.selection(metadata.regularAndStaticColumns().without(v1)), metadata, MessagingService.VERSION_30);
    testRoundTrip(ColumnFilter.selection(metadata.regularAndStaticColumns().without(v1)), metadata, MessagingService.VERSION_3014);
    testRoundTrip(ColumnFilter.selection(metadata.regularAndStaticColumns().without(v1)), metadata, MessagingService.VERSION_40);
    testRoundTrip(ColumnFilter.selection(metadata.regularAndStaticColumns().without(v1).without(s1)), metadata, MessagingService.VERSION_30);
    testRoundTrip(ColumnFilter.selection(metadata.regularAndStaticColumns().without(v1).without(s1)), metadata, MessagingService.VERSION_3014);
    testRoundTrip(ColumnFilter.selection(metadata.regularAndStaticColumns().without(v1).without(s1)), metadata, MessagingService.VERSION_40);
    columnFilter = ColumnFilter.selection(metadata, metadata.regularAndStaticColumns().without(v1));
    testRoundTrip(columnFilter, ColumnFilter.Serializer.maybeUpdateForBackwardCompatility(columnFilter, MessagingService.VERSION_30), metadata, MessagingService.VERSION_30);
    testRoundTrip(columnFilter, ColumnFilter.Serializer.maybeUpdateForBackwardCompatility(columnFilter, MessagingService.VERSION_3014), metadata, MessagingService.VERSION_3014);
    testRoundTrip(columnFilter, metadata, MessagingService.VERSION_40);
    columnFilter = ColumnFilter.selection(metadata, metadata.regularAndStaticColumns().without(v1).without(s1));
    testRoundTrip(columnFilter, ColumnFilter.Serializer.maybeUpdateForBackwardCompatility(columnFilter, MessagingService.VERSION_30), metadata, MessagingService.VERSION_30);
    testRoundTrip(columnFilter, ColumnFilter.Serializer.maybeUpdateForBackwardCompatility(columnFilter, MessagingService.VERSION_3014), metadata, MessagingService.VERSION_3014);
    testRoundTrip(columnFilter, metadata, MessagingService.VERSION_40);
}

@Test
public void testColumnFilterConstruction() {
    // all regular column
    TableMetadata metadata = TableMetadata.builder("ks", "table").partitioner(Murmur3Partitioner.instance).addPartitionKeyColumn("pk", Int32Type.instance).addClusteringColumn("ck", Int32Type.instance).addRegularColumn("v1", Int32Type.instance).addRegularColumn("v2", Int32Type.instance).addRegularColumn("v3", Int32Type.instance).build();
    ColumnFilter columnFilter = ColumnFilter.all(metadata);
    assertTrue(columnFilter.fetchAllRegulars);
    assertEquals(metadata.regularAndStaticColumns(), columnFilter.fetched);
    assertNull(columnFilter.queried);
    assertEquals("*", columnFilter.toString());
    RegularAndStaticColumns queried = RegularAndStaticColumns.builder().add(metadata.getColumn(ByteBufferUtil.bytes("v1"))).build();
    columnFilter = ColumnFilter.selection(queried);
    assertFalse(columnFilter.fetchAllRegulars);
    assertEquals(queried, columnFilter.fetched);
    assertEquals(queried, columnFilter.queried);
    assertEquals("v1", columnFilter.toString());
    // with static column
    metadata = TableMetadata.builder("ks", "table").partitioner(Murmur3Partitioner.instance).addPartitionKeyColumn("pk", Int32Type.instance).addClusteringColumn("ck", Int32Type.instance).addStaticColumn("sc1", Int32Type.instance).addStaticColumn("sc2", Int32Type.instance).addRegularColumn("v1", Int32Type.instance).build();
    columnFilter = ColumnFilter.all(metadata);
    assertTrue(columnFilter.fetchAllRegulars);
    assertEquals(metadata.regularAndStaticColumns(), columnFilter.fetched);
    assertNull(columnFilter.queried);
    assertEquals("*", columnFilter.toString());
    queried = RegularAndStaticColumns.builder().add(metadata.getColumn(ByteBufferUtil.bytes("v1"))).build();
    columnFilter = ColumnFilter.selection(metadata, queried);
    assertEquals("v1", columnFilter.toString());
    // only static
    metadata = TableMetadata.builder("ks", "table").partitioner(Murmur3Partitioner.instance).addPartitionKeyColumn("pk", Int32Type.instance).addClusteringColumn("ck", Int32Type.instance).addStaticColumn("sc", Int32Type.instance).build();
    columnFilter = ColumnFilter.all(metadata);
    assertTrue(columnFilter.fetchAllRegulars);
    assertEquals(metadata.regularAndStaticColumns(), columnFilter.fetched);
    assertNull(columnFilter.queried);
    assertEquals("*", columnFilter.toString());
    // with collection type
    metadata = TableMetadata.builder("ks", "table").partitioner(Murmur3Partitioner.instance).addPartitionKeyColumn("pk", Int32Type.instance).addClusteringColumn("ck", Int32Type.instance).addRegularColumn("v1", Int32Type.instance).addRegularColumn("set", SetType.getInstance(Int32Type.instance, true)).build();
    columnFilter = ColumnFilter.all(metadata);
    assertTrue(columnFilter.fetchAllRegulars);
    assertEquals(metadata.regularAndStaticColumns(), columnFilter.fetched);
    assertNull(columnFilter.queried);
    assertEquals("*", columnFilter.toString());
    columnFilter = ColumnFilter.selectionBuilder().add(metadata.getColumn(ByteBufferUtil.bytes("v1"))).select(metadata.getColumn(ByteBufferUtil.bytes("set")), CellPath.create(ByteBufferUtil.bytes(1))).build();
    assertEquals("set[1], v1", columnFilter.toString());
}

/**
 * Tests whether a filter fetches and/or queries columns and cells.
 */
@Test
public void testFetchedQueried() {
    TableMetadata metadata = TableMetadata.builder("ks", "table").partitioner(Murmur3Partitioner.instance).addPartitionKeyColumn("k", Int32Type.instance).addRegularColumn("simple", Int32Type.instance).addRegularColumn("complex", SetType.getInstance(Int32Type.instance, true)).build();
    ColumnMetadata simple = metadata.getColumn(ByteBufferUtil.bytes("simple"));
    ColumnMetadata complex = metadata.getColumn(ByteBufferUtil.bytes("complex"));
    CellPath path1 = CellPath.create(ByteBufferUtil.bytes(1));
    CellPath path2 = CellPath.create(ByteBufferUtil.bytes(2));
    ColumnFilter filter;
    // select only the simple column, without table metadata
    filter = ColumnFilter.selection(RegularAndStaticColumns.builder().add(simple).build());
    assertFetchedQueried(true, true, filter, simple);
    assertFetchedQueried(false, false, filter, complex);
    assertFetchedQueried(false, false, filter, complex, path1);
    assertFetchedQueried(false, false, filter, complex, path2);
    // select only the complex column, without table metadata
    filter = ColumnFilter.selection(RegularAndStaticColumns.builder().add(complex).build());
    assertFetchedQueried(false, false, filter, simple);
    assertFetchedQueried(true, true, filter, complex);
    assertFetchedQueried(true, true, filter, complex, path1);
    assertFetchedQueried(true, true, filter, complex, path2);
    // select both the simple and complex columns, without table metadata
    filter = ColumnFilter.selection(RegularAndStaticColumns.builder().add(simple).add(complex).build());
    assertFetchedQueried(true, true, filter, simple);
    assertFetchedQueried(true, true, filter, complex);
    assertFetchedQueried(true, true, filter, complex, path1);
    assertFetchedQueried(true, true, filter, complex, path2);
    // select only the simple column, with table metadata
    filter = ColumnFilter.selection(metadata, RegularAndStaticColumns.builder().add(simple).build());
    assertFetchedQueried(true, true, filter, simple);
    assertFetchedQueried(true, false, filter, complex);
    assertFetchedQueried(true, false, filter, complex, path1);
    assertFetchedQueried(true, false, filter, complex, path2);
    // select only the complex column, with table metadata
    filter = ColumnFilter.selection(metadata, RegularAndStaticColumns.builder().add(complex).build());
    assertFetchedQueried(true, false, filter, simple);
    assertFetchedQueried(true, true, filter, complex);
    assertFetchedQueried(true, true, filter, complex, path1);
    assertFetchedQueried(true, true, filter, complex, path2);
    // select both the simple and complex columns, with table metadata
    filter = ColumnFilter.selection(metadata, RegularAndStaticColumns.builder().add(simple).add(complex).build());
    assertFetchedQueried(true, true, filter, simple);
    assertFetchedQueried(true, true, filter, complex);
    assertFetchedQueried(true, true, filter, complex, path1);
    assertFetchedQueried(true, true, filter, complex, path2);
    // select only the simple column, with selection builder
    filter = ColumnFilter.selectionBuilder().add(simple).build();
    assertFetchedQueried(true, true, filter, simple);
    assertFetchedQueried(false, false, filter, complex);
    assertFetchedQueried(false, false, filter, complex, path1);
    assertFetchedQueried(false, false, filter, complex, path2);
    // select only a cell of the complex column, with selection builder
    filter = ColumnFilter.selectionBuilder().select(complex, path1).build();
    assertFetchedQueried(false, false, filter, simple);
    assertFetchedQueried(true, true, filter, complex);
    assertFetchedQueried(true, true, filter, complex, path1);
    assertFetchedQueried(true, false, filter, complex, path2);
    // select both the simple column and a cell of the complex column, with selection builder
    filter = ColumnFilter.selectionBuilder().add(simple).select(complex, path1).build();
    assertFetchedQueried(true, true, filter, simple);
    assertFetchedQueried(true, true, filter, complex);
    assertFetchedQueried(true, true, filter, complex, path1);
    assertFetchedQueried(true, false, filter, complex, path2);
}

@Test
public void testCQLFilterClose() {
    // CASSANDRA-15126
    TableMetadata metadata = TableMetadata.builder("testks", "testcf").addPartitionKeyColumn("pk", Int32Type.instance).addStaticColumn("s", Int32Type.instance).addRegularColumn("r", Int32Type.instance).build();
    ColumnMetadata s = metadata.getColumn(new ColumnIdentifier("s", true));
    ColumnMetadata r = metadata.getColumn(new ColumnIdentifier("r", true));
    ByteBuffer one = Int32Type.instance.decompose(1);
    RowFilter filter = RowFilter.NONE.withNewExpressions(new ArrayList<>());
    filter.add(s, Operator.NEQ, one);
    AtomicBoolean closed = new AtomicBoolean();
    UnfilteredPartitionIterator iter = filter.filter(new SingletonUnfilteredPartitionIterator(new UnfilteredRowIterator() {

        public DeletionTime partitionLevelDeletion() {
            return null;
        }

        public EncodingStats stats() {
            return null;
        }

        public TableMetadata metadata() {
            return metadata;
        }

        public boolean isReverseOrder() {
            return false;
        }

        public RegularAndStaticColumns columns() {
            return null;
        }

        public DecoratedKey partitionKey() {
            return null;
        }

        public boolean hasNext() {
            return false;
        }

        public Unfiltered next() {
            return null;
        }

        public Row staticRow() {
            return BTreeRow.create(Clustering.STATIC_CLUSTERING, LivenessInfo.EMPTY, Row.Deletion.LIVE, BTree.singleton(new BufferCell(s, 1, Cell.NO_TTL, Cell.NO_DELETION_TIME, one, null)));
        }

        public void close() {
            closed.set(true);
        }
    }), 1);
    Assert.assertFalse(iter.hasNext());
    Assert.assertTrue(closed.get());
    filter = RowFilter.NONE.withNewExpressions(new ArrayList<>());
    filter.add(r, Operator.NEQ, one);
    closed.set(false);
    iter = filter.filter(new SingletonUnfilteredPartitionIterator(new UnfilteredRowIterator() {

        boolean hasNext = true;

        public DeletionTime partitionLevelDeletion() {
            return null;
        }

        public EncodingStats stats() {
            return null;
        }

        public TableMetadata metadata() {
            return metadata;
        }

        public boolean isReverseOrder() {
            return false;
        }

        public RegularAndStaticColumns columns() {
            return null;
        }

        public DecoratedKey partitionKey() {
            return null;
        }

        public Row staticRow() {
            return Rows.EMPTY_STATIC_ROW;
        }

        public boolean hasNext() {
            boolean r = hasNext;
            hasNext = false;
            return r;
        }

        public Unfiltered next() {
            return BTreeRow.create(Clustering.EMPTY, LivenessInfo.EMPTY, Row.Deletion.LIVE, BTree.singleton(new BufferCell(r, 1, Cell.NO_TTL, Cell.NO_DELETION_TIME, one, null)));
        }

        public void close() {
            closed.set(true);
        }
    }), 1);
    Assert.assertFalse(iter.hasNext());
    Assert.assertTrue(closed.get());
}

@Test
public void testIntersectsSingleSlice() {
    List<AbstractType<?>> types = new ArrayList<>();
    types.add(Int32Type.instance);
    types.add(Int32Type.instance);
    types.add(Int32Type.instance);
    ClusteringComparator cc = new ClusteringComparator(types);
    ClusteringPrefix.Kind sk = INCL_START_BOUND;
    ClusteringPrefix.Kind ek = INCL_END_BOUND;
    // filter falls entirely before sstable
    Slice slice = Slice.make(makeBound(sk, 0, 0, 0), makeBound(ek, 1, 0, 0));
    assertFalse(slice.intersects(cc, columnNames(2, 0, 0), columnNames(3, 0, 0)));
    // same case, but with empty start
    slice = Slice.make(makeBound(sk), makeBound(ek, 1, 0, 0));
    assertFalse(slice.intersects(cc, columnNames(2, 0, 0), columnNames(3, 0, 0)));
    // same case, but with missing components for start
    slice = Slice.make(makeBound(sk, 0), makeBound(ek, 1, 0, 0));
    assertFalse(slice.intersects(cc, columnNames(2, 0, 0), columnNames(3, 0, 0)));
    // same case, but with missing components for start and end
    slice = Slice.make(makeBound(sk, 0), makeBound(ek, 1, 0));
    assertFalse(slice.intersects(cc, columnNames(2, 0, 0), columnNames(3, 0, 0)));
    // end of slice matches start of sstable for the first component, but not the second component
    slice = Slice.make(makeBound(sk, 0, 0, 0), makeBound(ek, 1, 0, 0));
    assertFalse(slice.intersects(cc, columnNames(1, 1, 0), columnNames(3, 0, 0)));
    // same case, but with missing components for start
    slice = Slice.make(makeBound(sk, 0), makeBound(ek, 1, 0, 0));
    assertFalse(slice.intersects(cc, columnNames(1, 1, 0), columnNames(3, 0, 0)));
    // same case, but with missing components for start and end
    slice = Slice.make(makeBound(sk, 0), makeBound(ek, 1, 0));
    assertFalse(slice.intersects(cc, columnNames(1, 1, 0), columnNames(3, 0, 0)));
    // first two components match, but not the last
    slice = Slice.make(makeBound(sk, 0, 0, 0), makeBound(ek, 1, 1, 0));
    assertFalse(slice.intersects(cc, columnNames(1, 1, 1), columnNames(3, 1, 1)));
    // all three components in slice end match the start of the sstable
    slice = Slice.make(makeBound(sk, 0, 0, 0), makeBound(ek, 1, 1, 1));
    assertTrue(slice.intersects(cc, columnNames(1, 1, 1), columnNames(3, 1, 1)));
    // filter falls entirely after sstable
    slice = Slice.make(makeBound(sk, 4, 0, 0), makeBound(ek, 4, 0, 0));
    assertFalse(slice.intersects(cc, columnNames(2, 0, 0), columnNames(3, 0, 0)));
    // same case, but with empty end
    slice = Slice.make(makeBound(sk, 4, 0, 0), makeBound(ek));
    assertFalse(slice.intersects(cc, columnNames(2, 0, 0), columnNames(3, 0, 0)));
    // same case, but with missing components for end
    slice = Slice.make(makeBound(sk, 4, 0, 0), makeBound(ek, 1));
    assertFalse(slice.intersects(cc, columnNames(2, 0, 0), columnNames(3, 0, 0)));
    // same case, but with missing components for start and end
    slice = Slice.make(makeBound(sk, 4, 0), makeBound(ek, 1));
    assertFalse(slice.intersects(cc, columnNames(2, 0, 0), columnNames(3, 0, 0)));
    // start of slice matches end of sstable for the first component, but not the second component
    slice = Slice.make(makeBound(sk, 1, 1, 1), makeBound(ek, 2, 0, 0));
    assertFalse(slice.intersects(cc, columnNames(0, 0, 0), columnNames(1, 0, 0)));
    // start of slice matches end of sstable for the first two components, but not the last component
    slice = Slice.make(makeBound(sk, 1, 1, 1), makeBound(ek, 2, 0, 0));
    assertFalse(slice.intersects(cc, columnNames(0, 0, 0), columnNames(1, 1, 0)));
    // all three components in the slice start match the end of the sstable
    slice = Slice.make(makeBound(sk, 1, 1, 1), makeBound(ek, 2, 0, 0));
    assertTrue(slice.intersects(cc, columnNames(0, 0, 0), columnNames(1, 1, 1)));
    // slice covers entire sstable (with no matching edges)
    slice = Slice.make(makeBound(sk, 0, 0, 0), makeBound(ek, 2, 0, 0));
    assertTrue(slice.intersects(cc, columnNames(1, 0, 0), columnNames(1, 1, 1)));
    // same case, but with empty ends
    slice = Slice.make(makeBound(sk), makeBound(ek));
    assertTrue(slice.intersects(cc, columnNames(1, 0, 0), columnNames(1, 1, 1)));
    // same case, but with missing components
    slice = Slice.make(makeBound(sk, 0), makeBound(ek, 2, 0));
    assertTrue(slice.intersects(cc, columnNames(1, 0, 0), columnNames(1, 1, 1)));
    // slice covers entire sstable (with matching start)
    slice = Slice.make(makeBound(sk, 1, 0, 0), makeBound(ek, 2, 0, 0));
    assertTrue(slice.intersects(cc, columnNames(1, 0, 0), columnNames(1, 1, 1)));
    // slice covers entire sstable (with matching end)
    slice = Slice.make(makeBound(sk, 0, 0, 0), makeBound(ek, 1, 1, 1));
    assertTrue(slice.intersects(cc, columnNames(1, 0, 0), columnNames(1, 1, 1)));
    // slice covers entire sstable (with matching start and end)
    slice = Slice.make(makeBound(sk, 1, 0, 0), makeBound(ek, 1, 1, 1));
    assertTrue(slice.intersects(cc, columnNames(1, 0, 0), columnNames(1, 1, 1)));
    // slice falls entirely within sstable (with matching start)
    slice = Slice.make(makeBound(sk, 1, 0, 0), makeBound(ek, 1, 1, 0));
    assertTrue(slice.intersects(cc, columnNames(1, 0, 0), columnNames(1, 1, 1)));
    // same case, but with a missing end component
    slice = Slice.make(makeBound(sk, 1, 0, 0), makeBound(ek, 1, 1));
    assertTrue(slice.intersects(cc, columnNames(1, 0, 0), columnNames(1, 1, 1)));
    // slice falls entirely within sstable (with matching end)
    slice = Slice.make(makeBound(sk, 1, 1, 0), makeBound(ek, 1, 1, 1));
    assertTrue(slice.intersects(cc, columnNames(1, 0, 0), columnNames(1, 1, 1)));
    // same case, but with a missing start component
    slice = Slice.make(makeBound(sk, 1, 1), makeBound(ek, 1, 1, 1));
    assertTrue(slice.intersects(cc, columnNames(1, 0, 0), columnNames(1, 1, 1)));
    // slice falls entirely within sstable
    slice = Slice.make(makeBound(sk, 1, 1, 0), makeBound(ek, 1, 1, 1));
    assertTrue(slice.intersects(cc, columnNames(1, 0, 0), columnNames(2, 2, 2)));
    // same case, but with a missing start component
    slice = Slice.make(makeBound(sk, 1, 1), makeBound(ek, 1, 1, 1));
    assertTrue(slice.intersects(cc, columnNames(1, 0, 0), columnNames(2, 2, 2)));
    // same case, but with a missing start and end components
    slice = Slice.make(makeBound(sk, 1), makeBound(ek, 1, 2));
    assertTrue(slice.intersects(cc, columnNames(1, 0, 0), columnNames(2, 2, 2)));
    // same case, but with an equal first component and missing start and end components
    slice = Slice.make(makeBound(sk, 1), makeBound(ek, 1));
    assertTrue(slice.intersects(cc, columnNames(1, 0, 0), columnNames(2, 2, 2)));
    // slice falls entirely within sstable (slice start and end are the same)
    slice = Slice.make(makeBound(sk, 1, 1, 1), makeBound(ek, 1, 1, 1));
    assertTrue(slice.intersects(cc, columnNames(1, 0, 0), columnNames(2, 2, 2)));
    // slice starts within sstable, empty end
    slice = Slice.make(makeBound(sk, 1, 1, 1), makeBound(ek));
    assertTrue(slice.intersects(cc, columnNames(1, 0, 0), columnNames(2, 0, 0)));
    // same case, but with missing end components
    slice = Slice.make(makeBound(sk, 1, 1, 1), makeBound(ek, 3));
    assertTrue(slice.intersects(cc, columnNames(1, 0, 0), columnNames(2, 0, 0)));
    // slice starts within sstable (matching sstable start), empty end
    slice = Slice.make(makeBound(sk, 1, 0, 0), makeBound(ek));
    assertTrue(slice.intersects(cc, columnNames(1, 0, 0), columnNames(2, 0, 0)));
    // same case, but with missing end components
    slice = Slice.make(makeBound(sk, 1, 0, 0), makeBound(ek, 3));
    assertTrue(slice.intersects(cc, columnNames(1, 0, 0), columnNames(2, 0, 0)));
    // slice starts within sstable (matching sstable end), empty end
    slice = Slice.make(makeBound(sk, 2, 0, 0), makeBound(ek));
    assertTrue(slice.intersects(cc, columnNames(1, 0, 0), columnNames(2, 0, 0)));
    // same case, but with missing end components
    slice = Slice.make(makeBound(sk, 2, 0, 0), makeBound(ek, 3));
    assertTrue(slice.intersects(cc, columnNames(1, 0, 0), columnNames(2, 0, 0)));
    // slice ends within sstable, empty end
    slice = Slice.make(makeBound(sk), makeBound(ek, 1, 1, 1));
    assertTrue(slice.intersects(cc, columnNames(1, 0, 0), columnNames(2, 0, 0)));
    // same case, but with missing start components
    slice = Slice.make(makeBound(sk, 0), makeBound(ek, 1, 1, 1));
    assertTrue(slice.intersects(cc, columnNames(1, 0, 0), columnNames(2, 0, 0)));
    // slice ends within sstable (matching sstable start), empty start
    slice = Slice.make(makeBound(sk), makeBound(ek, 1, 0, 0));
    assertTrue(slice.intersects(cc, columnNames(1, 0, 0), columnNames(2, 0, 0)));
    // same case, but with missing start components
    slice = Slice.make(makeBound(sk, 0), makeBound(ek, 1, 0, 0));
    assertTrue(slice.intersects(cc, columnNames(1, 0, 0), columnNames(2, 0, 0)));
    // slice ends within sstable (matching sstable end), empty start
    slice = Slice.make(makeBound(sk), makeBound(ek, 2, 0, 0));
    assertTrue(slice.intersects(cc, columnNames(1, 0, 0), columnNames(2, 0, 0)));
    // same case, but with missing start components
    slice = Slice.make(makeBound(sk, 0), makeBound(ek, 2, 0, 0));
    assertTrue(slice.intersects(cc, columnNames(1, 0, 0), columnNames(2, 0, 0)));
    // empty min/max column names
    slice = Slice.make(makeBound(sk), makeBound(ek));
    assertTrue(slice.intersects(cc, columnNames(), columnNames()));
    slice = Slice.make(makeBound(sk, 1), makeBound(ek));
    assertTrue(slice.intersects(cc, columnNames(), columnNames()));
    slice = Slice.make(makeBound(sk), makeBound(ek, 1));
    assertTrue(slice.intersects(cc, columnNames(), columnNames()));
    slice = Slice.make(makeBound(sk, 1), makeBound(ek, 1));
    assertTrue(slice.intersects(cc, columnNames(), columnNames()));
    slice = Slice.make(makeBound(sk), makeBound(ek));
    assertTrue(slice.intersects(cc, columnNames(), columnNames(1)));
    slice = Slice.make(makeBound(sk), makeBound(ek, 1));
    assertTrue(slice.intersects(cc, columnNames(), columnNames(1)));
    slice = Slice.make(makeBound(sk), makeBound(ek, 1));
    assertTrue(slice.intersects(cc, columnNames(), columnNames(2)));
    slice = Slice.make(makeBound(sk), makeBound(ek, 2));
    assertTrue(slice.intersects(cc, columnNames(), columnNames(1)));
    slice = Slice.make(makeBound(sk, 2), makeBound(ek, 3));
    assertFalse(slice.intersects(cc, columnNames(), columnNames(1)));
    // basic check on reversed slices
    slice = Slice.make(makeBound(sk, 1, 0, 0), makeBound(ek, 0, 0, 0));
    assertFalse(slice.intersects(cc, columnNames(2, 0, 0), columnNames(3, 0, 0)));
    slice = Slice.make(makeBound(sk, 1, 0, 0), makeBound(ek, 0, 0, 0));
    assertFalse(slice.intersects(cc, columnNames(1, 1, 0), columnNames(3, 0, 0)));
    slice = Slice.make(makeBound(sk, 1, 1, 1), makeBound(ek, 1, 1, 0));
    assertTrue(slice.intersects(cc, columnNames(1, 0, 0), columnNames(2, 2, 2)));
}

@Test
public void testDifferentMinMaxLengths() {
    List<AbstractType<?>> types = new ArrayList<>();
    types.add(Int32Type.instance);
    types.add(Int32Type.instance);
    types.add(Int32Type.instance);
    ClusteringComparator cc = new ClusteringComparator(types);
    ClusteringPrefix.Kind sk = INCL_START_BOUND;
    ClusteringPrefix.Kind ek = INCL_END_BOUND;
    // slice does intersect
    Slice slice = Slice.make(makeBound(sk), makeBound(ek));
    assertTrue(slice.intersects(cc, columnNames(), columnNames(1)));
    slice = Slice.make(makeBound(sk), makeBound(ek));
    assertTrue(slice.intersects(cc, columnNames(1), columnNames(1, 2)));
    slice = Slice.make(makeBound(sk), makeBound(ek, 1));
    assertTrue(slice.intersects(cc, columnNames(), columnNames(1)));
    slice = Slice.make(makeBound(sk, 1), makeBound(ek));
    assertTrue(slice.intersects(cc, columnNames(), columnNames(1)));
    slice = Slice.make(makeBound(sk, 1), makeBound(ek, 1));
    assertTrue(slice.intersects(cc, columnNames(), columnNames(1)));
    slice = Slice.make(makeBound(sk, 0), makeBound(ek, 1, 2, 3));
    assertTrue(slice.intersects(cc, columnNames(), columnNames(1)));
    slice = Slice.make(makeBound(sk, 1, 2, 3), makeBound(ek, 2));
    assertTrue(slice.intersects(cc, columnNames(), columnNames(1)));
    // slice does not intersect
    slice = Slice.make(makeBound(sk, 2), makeBound(ek, 3, 4, 5));
    assertFalse(slice.intersects(cc, columnNames(), columnNames(1)));
    slice = Slice.make(makeBound(sk, 0), makeBound(ek, 0, 1, 2));
    assertFalse(slice.intersects(cc, columnNames(1), columnNames(1, 2)));
}

