    key.putShort((short) 14);
    key.rewind();
    try {
        comparator.validate(key);
        fail("Should not validate");
    } catch (MarshalException e) {
        assert e.toString().contains("should be 16 or 0 bytes");
    }
    key = createCompositeKey("test1", UUID.randomUUID(), 42, false);
    try {
        comparator.validate(key);
        fail("Should not validate");
