}

@Test
public void test3Sort() {
    ByteBuffer zeroBB = DecimalType.instance.decompose(zero);
    ByteBuffer minusBB = DecimalType.instance.decompose(minus);
    ByteBuffer lowBB = DecimalType.instance.decompose(low);
    ByteBuffer highBB = DecimalType.instance.decompose(high);
    ByteBuffer[] array = { highBB, minusBB, lowBB, lowBB, zeroBB, minusBB };
    // Sort the array of ByteBuffer using a DecimalType comparator
    Arrays.sort(array, DecimalType.instance);
    // Check that the array is in order
    for (int i = 1; i < array.length; i++) {
        BigDecimal i0 = DecimalType.instance.compose(array[i - 1]);
        BigDecimal i1 = DecimalType.instance.compose(array[i]);
        assertTrue("#" + i, i0.compareTo(i1) <= 0);
    }
}

@Test
public void testEndOfComponent() {
    ByteBuffer[] cnames = { createDynamicCompositeKey("test1", uuids[0], -1, false), createDynamicCompositeKey("test1", uuids[1], 24, false), createDynamicCompositeKey("test1", uuids[1], 42, false), createDynamicCompositeKey("test1", uuids[1], 83, false), createDynamicCompositeKey("test1", uuids[2], -1, false), createDynamicCompositeKey("test1", uuids[2], 42, false) };
    ByteBuffer start = createDynamicCompositeKey("test1", uuids[1], -1, false);
    ByteBuffer stop = createDynamicCompositeKey("test1", uuids[1], -1, true);
    for (int i = 0; i < 1; ++i) {
        assert comparator.compare(start, cnames[i]) > 0;
        assert comparator.compare(stop, cnames[i]) > 0;
    }
    for (int i = 1; i < 4; ++i) {
        assert comparator.compare(start, cnames[i]) < 0;
        assert comparator.compare(stop, cnames[i]) > 0;
    }
    for (int i = 4; i < cnames.length; ++i) {
        assert comparator.compare(start, cnames[i]) < 0;
        assert comparator.compare(stop, cnames[i]) < 0;
    }
}

