    // concat with different columns
    iter1 = rows(metadata.regularAndStaticColumns().without(v1Metadata), 1, row(1, cell(v2Metadata, 1)), row(2, cell(v2Metadata, 2)));
    iter2 = rows(metadata.regularAndStaticColumns().without(v2Metadata), 1, row(3, cell(v1Metadata, 3)), row(4, cell(v1Metadata, 4)));
