@Test
public /**
 * [0,1],[0,5],[1,8],[4,10] = [0, 10]
 * [15,19][19,20] = [15,20]
 * [21, 22] = [21,22]
 */
void testGetNonOverlappingBounds() {
    List<Bounds<Token>> bounds = new LinkedList<>();
    bounds.add(bounds(19, 20));
    bounds.add(bounds(0, 1));
    bounds.add(bounds(4, 10));
    bounds.add(bounds(15, 19));
    bounds.add(bounds(0, 5));
    bounds.add(bounds(21, 22));
    bounds.add(bounds(1, 8));
    Set<Bounds<Token>> nonOverlappingBounds = Bounds.getNonOverlappingBounds(bounds);
    assertEquals(3, nonOverlappingBounds.size());
    assertTrue(nonOverlappingBounds.contains(bounds(0, 10)));
    assertTrue(nonOverlappingBounds.contains(bounds(15, 20)));
    assertTrue(nonOverlappingBounds.contains(bounds(21, 22)));
}

@Test
public void testGetSliceWithCollision() throws Exception {
    Keyspace keyspace = Keyspace.open(KEYSPACE1);
    ColumnFamilyStore cfs = keyspace.getColumnFamilyStore(CF);
    cfs.clearUnsafe();
    // token = 2, kq ordered after row below lexicographically
    insert("k1", "k2", "kq");
    // token = 4
    insert("key1", "key2", "key3");
    // token = 8
    insert("longKey1", "longKey2");
    List<FilteredPartition> partitions = Util.getAll(Util.cmd(cfs).fromKeyIncl("k2").toKeyIncl("key2").build());
    assert partitions.get(0).partitionKey().getKey().equals(ByteBufferUtil.bytes("k2"));
    assert partitions.get(1).partitionKey().getKey().equals(ByteBufferUtil.bytes("kq"));
    assert partitions.get(2).partitionKey().getKey().equals(ByteBufferUtil.bytes("key1"));
    assert partitions.get(3).partitionKey().getKey().equals(ByteBufferUtil.bytes("key2"));
}

