@Test
public void testDelayedResponse() {
    Gossiper.instance.buildSeedsList();
    int noOfSeeds = Gossiper.instance.seeds.size();
    final AtomicBoolean ackSend = new AtomicBoolean(false);
    MockMessagingSpy spySyn = MockMessagingService.when(verb(Verb.GOSSIP_DIGEST_SYN)).respondN((msgOut, to) -> {
        // ACK once to finish shadow round, then busy-spin until gossiper has been enabled
        // and then respond with remaining ACKs from other seeds
        if (!ackSend.compareAndSet(false, true)) {
            while (!Gossiper.instance.isEnabled()) ;
        }
        HeartBeatState hb = new HeartBeatState(123, 456);
        EndpointState state = new EndpointState(hb);
        GossipDigestAck payload = new GossipDigestAck(Collections.singletonList(new GossipDigest(to, hb.getGeneration(), hb.getHeartBeatVersion())), Collections.singletonMap(to, state));
        logger.debug("Simulating digest ACK response");
        return Message.builder(Verb.GOSSIP_DIGEST_ACK, payload).from(to).build();
    }, noOfSeeds);
    // GossipDigestAckVerbHandler will send ack2 for each ack received (after the shadow round)
    MockMessagingSpy spyAck2 = MockMessagingService.when(verb(Verb.GOSSIP_DIGEST_ACK2)).dontReply();
    // Migration request messages should not be emitted during shadow round
    MockMessagingSpy spyMigrationReq = MockMessagingService.when(verb(Verb.SCHEMA_PULL_REQ)).dontReply();
    try {
        StorageService.instance.initServer();
    } catch (Exception e) {
        assertEquals("Unable to contact any seeds!", e.getMessage());
    }
    // we expect one SYN for each seed during shadow round + additional SYNs after gossiper has been enabled
    assertTrue(spySyn.messagesIntercepted > noOfSeeds);
    // we don't expect to emit any GOSSIP_DIGEST_ACK2 or SCHEMA_PULL messages
    assertEquals(0, spyAck2.messagesIntercepted);
    assertEquals(0, spyMigrationReq.messagesIntercepted);
}

@Test
public void testReadMethods() throws IOException {
    // Make sure this array is bigger than the reader buffer size
    // so we test updating the crc across buffer boundaries
    byte[] b = new byte[RandomAccessReader.DEFAULT_BUFFER_SIZE * 2];
    for (int i = 0; i < b.length; i++) b[i] = (byte) i;
    ByteBuffer buffer;
    // fill a bytebuffer with some input
    try (DataOutputBuffer out = new DataOutputBuffer()) {
        out.write(127);
        out.write(b);
        out.writeBoolean(false);
        out.writeByte(10);
        out.writeChar('t');
        out.writeDouble(3.3);
        out.writeFloat(2.2f);
        out.writeInt(42);
        out.writeLong(Long.MAX_VALUE);
        out.writeShort(Short.MIN_VALUE);
        out.writeUTF("utf");
        out.writeVInt(67L);
        out.writeUnsignedVInt(88L);
        out.writeBytes("abcdefghi");
        buffer = out.buffer();
    }
    // calculate expected CRC
    CRC32 crc = new CRC32();
    FBUtilities.updateChecksum(crc, buffer);
    // save the buffer to file to create a RAR
    File file = FileUtils.createTempFile("testReadMethods", "1");
    file.deleteOnExit();
    try (SequentialWriter writer = new SequentialWriter(file)) {
        writer.write(buffer);
        writer.writeInt((int) crc.getValue());
        writer.finish();
    }
    assertTrue(file.exists());
    assertEquals(buffer.remaining() + 4, file.length());
    try (ChecksummedDataInput reader = ChecksummedDataInput.open(file)) {
        reader.limit(buffer.remaining() + 4);
        // assert that we read all the right values back
        assertEquals(127, reader.read());
        byte[] bytes = new byte[b.length];
        reader.readFully(bytes);
        assertTrue(Arrays.equals(bytes, b));
        assertEquals(false, reader.readBoolean());
        assertEquals(10, reader.readByte());
        assertEquals('t', reader.readChar());
        assertEquals(3.3, reader.readDouble());
        assertEquals(2.2f, reader.readFloat());
        assertEquals(42, reader.readInt());
        assertEquals(Long.MAX_VALUE, reader.readLong());
        assertEquals(Short.MIN_VALUE, reader.readShort());
        assertEquals("utf", reader.readUTF());
        assertEquals(67L, reader.readVInt());
        assertEquals(88L, reader.readUnsignedVInt());
        assertEquals("abcdefghi", new String(ByteBufferUtil.read(reader, 9).array(), StandardCharsets.UTF_8));
        // assert that the crc matches, and that we've read exactly as many bytes as expected
        assertTrue(reader.checkCrc());
        assertTrue(reader.isEOF());
        reader.checkLimit(0);
    }
}

@Test
public void testResetCrc() throws IOException {
    CRC32 crc = new CRC32();
    ByteBuffer buffer;
    // fill a bytebuffer with some input
    try (DataOutputBuffer out = new DataOutputBuffer()) {
        out.write(127);
        out.writeBoolean(false);
        out.writeByte(10);
        out.writeChar('t');
        buffer = out.buffer();
        FBUtilities.updateChecksum(crc, buffer);
        out.writeInt((int) crc.getValue());
        int bufferPos = out.getLength();
        out.writeDouble(3.3);
        out.writeFloat(2.2f);
        out.writeInt(42);
        buffer = out.buffer();
        buffer.position(bufferPos);
        crc.reset();
        FBUtilities.updateChecksum(crc, buffer);
        out.writeInt((int) crc.getValue());
        buffer = out.buffer();
    }
    // save the buffer to file to create a RAR
    File file = FileUtils.createTempFile("testResetCrc", "1");
    file.deleteOnExit();
    try (SequentialWriter writer = new SequentialWriter(file)) {
        writer.write(buffer);
        writer.finish();
    }
    assertTrue(file.exists());
    assertEquals(buffer.remaining(), file.length());
    try (ChecksummedDataInput reader = ChecksummedDataInput.open(file)) {
        reader.limit(buffer.remaining());
        // assert that we read all the right values back
        assertEquals(127, reader.read());
        assertEquals(false, reader.readBoolean());
        assertEquals(10, reader.readByte());
        assertEquals('t', reader.readChar());
        assertTrue(reader.checkCrc());
        reader.resetCrc();
        assertEquals(3.3, reader.readDouble());
        assertEquals(2.2f, reader.readFloat());
        assertEquals(42, reader.readInt());
        assertTrue(reader.checkCrc());
        assertTrue(reader.isEOF());
    }
}

