    IEndpointSnitch snitch = new SimpleSnitch();
    DatabaseDescriptor.setEndpointSnitch(snitch);
    List<InetAddressAndPort> endpoints = Lists.newArrayList(InetAddressAndPort.getByName("127.0.0.1"), InetAddressAndPort.getByName("127.0.0.2"), InetAddressAndPort.getByName("127.0.0.3"), InetAddressAndPort.getByName("127.0.0.4"));
