    final PropertyFileSnitch snitch = new PropertyFileSnitch(/*refreshPeriodInSeconds*/
    1);
    checkEndpoint(snitch, host.getHostAddressAndPort(), "DC1", "RAC2");
    try {
        setNodeLive(host);
        Files.copy(effectiveFile, backupFile);
        // removes line if found
        replaceConfigFile(Collections.singletonMap(host.getHostAddressAndPort(), ""));
        Thread.sleep(1500);
        // unchanged
        checkEndpoint(snitch, host.getHostAddressAndPort(), "DC1", "RAC2");
        setNodeShutdown(host);
        // removes line if found
        replaceConfigFile(Collections.singletonMap(host.getHostAddressAndPort(), ""));
