 */
@Test
public void testChangeDefault() throws Exception {
    final InetAddressAndPort host = InetAddressAndPort.getByName("127.0.0.9");
    final PropertyFileSnitch snitch = new PropertyFileSnitch(/*refreshPeriodInSeconds*/
    1);
    // default
    checkEndpoint(snitch, host.getHostAddressAndPort(), "DC1", "r1");
    try {
        setNodeLive(host);
        Files.copy(effectiveFile, backupFile);
        // change default
        replaceConfigFile(Collections.singletonMap("default", "DC2:r2"));
        Thread.sleep(1500);
        // unchanged
        checkEndpoint(snitch, host.getHostAddressAndPort(), "DC1", "r1");
        setNodeShutdown(host);
        // change default again (refresh file update)
        replaceConfigFile(Collections.singletonMap("default", "DC2:r2"));
        Thread.sleep(1500);
        // default updated
        checkEndpoint(snitch, host.getHostAddressAndPort(), "DC2", "r2");
    } finally {
        restoreOrigConfigFile();
        setNodeShutdown(host);
    }
}

