        Snapshot snapshot = histogram.getSnapshot();
        assertEquals(0, snapshot.getValue(0.5), DOUBLE_ASSERT_DELTA);
        assertEquals(1, snapshot.getValue(0.99), DOUBLE_ASSERT_DELTA);
