    Map<InetAddressAndPort, IncomingRepairStreamTracker> tracker = ReduceHelper.createIncomingRepairStreamTrackers(differenceHolder);
    Map<Range<Token>, StreamFromOptions> ranges = tracker.get(A).getIncoming();
