@Test
public void testSslContextReload_HappyPath() throws IOException, InterruptedException {
    try {
        ServerEncryptionOptions options = addKeystoreOptions(encryptionOptions).withInternodeEncryption(ServerEncryptionOptions.InternodeEncryption.all);
        SSLFactory.initHotReloading(options, options, true);
        SslContext oldCtx = SSLFactory.getOrCreateSslContext(options, true, SSLFactory.SocketType.CLIENT, OpenSsl.isAvailable());
        File keystoreFile = new File(options.keystore);
        SSLFactory.checkCertFilesForHotReloading((ServerEncryptionOptions) options, options);
        keystoreFile.setLastModified(System.currentTimeMillis() + 15000);
        SSLFactory.checkCertFilesForHotReloading((ServerEncryptionOptions) options, options);
        ;
        SslContext newCtx = SSLFactory.getOrCreateSslContext(options, true, SSLFactory.SocketType.CLIENT, OpenSsl.isAvailable());
        Assert.assertNotSame(oldCtx, newCtx);
    } catch (Exception e) {
        throw e;
    } finally {
        DatabaseDescriptor.loadConfig();
    }
}

